MultiLanguageSpellData['it'][163988] = {name = "Ira Arcana: Dislocazione", additional_info = "1.5 s di lancio\n[q]L'Imperatore Mar'gok travolge un personaggio casuale con l'energia arcana, marchiandolo per 4 sec.\n\n Quando Ira Arcana termina, infligge 3591 danni da arcano e salta sul bersaglio alleato più vicino entro 200 m.\n\n Ogni volta che Ira Arcana salta su un nuovo bersaglio, i danni inflitti aumentano del 25% e la portata del salto diminuisce del 50%.\n\n Dislocazione: i personaggi Marchiati non possono allontanarsi di più di 10 m dalla posizione in cui sono stati marchiati."}
MultiLanguageSpellData['it'][163989] = {name = "Ira Arcana: Fortificazione", additional_info = "1.5 s di lancio\n[q]L'Imperatore Mar'gok travolge un personaggio casuale con l'energia arcana, marchiandolo per 4 sec.\n\n Quando Ira Arcana termina, infligge 3591 danni da arcano e salta sul bersaglio alleato più vicino entro 200 m.\n\n Ogni volta che Ira Arcana salta su un nuovo bersaglio, i danni inflitti aumentano del 25% e la portata del salto diminuisce del 25%.\n\n Fortificazione: la portata di Ira Arcana si riduce solo del 25% quando salta su un altro bersaglio."}
MultiLanguageSpellData['it'][163990] = {name = "Ira Arcana: Replicazione", additional_info = "1.5 s di lancio\n[q]L'Imperatore Mar'gok travolge un personaggio casuale con l'energia arcana, marchiandolo per 4 sec.\n\n Quando Ira Arcana termina, infligge 3591 danni da arcano e salta sul bersaglio alleato più vicino entro 200 m.\n\n Ogni volta che Ira Arcana salta su un nuovo bersaglio, i danni inflitti aumentano del 25% e la portata del salto diminuisce del 50%.\n\n Replicazione: Ira Arcana salta su due bersagli aggiuntivi la prima volta che salta, marchiandoli entrambi."}
