MultiLanguageSpellData['it'][165719] = {name = "Esplosione Sacra", additional_info = "15 mana\nIstantaneo\n[q]Genera un'esplosione di luce sacra intorno all'incantatore, infliggendo 147 danni da sacro a tutti i bersagli nemici entro 10 m e curando tutti i membri del gruppo entro 10 m di 3 . L'effetto non genera minaccia."}
