MultiLanguageSpellData['it'][165721] = {name = "Contrizione", additional_info = "Portata di 30 m\nCanalizzato (3 s di lancio)\n[q]Lancia una raffica di luce sacra contro il bersaglio, infliggendo 100 danni da sacro a un nemico ogni 1 s per 3 sec."}
MultiLanguageSpellData['it'][165722] = {name = "Sete di Sangue", additional_info = "Portata di mischia\n{Istantaneo} {10 s di recupero}\nRichiede Arma da mischia\n[q]Attacca istantaneamente il bersaglio, infliggendo il 120% dei danni dell'arma normali. Inoltre, gli attacchi in mischia a segno rigenerano l'1% della salute massima. L'effetto dura 10 sec."}
