MultiLanguageSpellData['it'][168280] = {name = "Potenziamento", additional_info = "Portata di 45 m\n2 s di lancio\n[q]Potenzia un alleato vicino, aumentandone i danni inflitti e le cure fornite. L'efficienza del potenziamento aumenta man mano che la salute dell'incantatore diminuisce."}
