MultiLanguageSpellData['it'][168286] = {name = "Dardo d'Acqua", additional_info = "Portata di 45 m\n2.5 s di lancio\n[q]Lancia un dardo d'acqua contro un bersaglio nemico, infliggendo danni da gelo."}
MultiLanguageSpellData['it'][168287] = {name = "The Avatar of Terokk: Kargath's Kill", additional_info = nil}
MultiLanguageSpellData['it'][168289] = {name = "Incantesimo di Prova di Archeologia", additional_info = "2 s di lancio\n[q]Anche se i Mantid usano la telaria e la seta imperiale, preferiscono un tipo di \"tessuto\" che si ricava dalle ali di diversi tipi di insetti, inclusi loro stessi. Questo stendardo ne è un esempio."}
MultiLanguageSpellData['it'][168290] = {name = "Ascia Sfregiata dei Lupi Bianchi", additional_info = "2 s di lancio 5\n[q]Per diventare parte integrante del Clan Lupi Bianchi, ogni membro deve portare a termine una missione in solitaria e ottenere l'amicizia di un lupo bianco. Non tutti riescono a passare questa prova, ma coloro che ce la fanno ottengono un nuovo compagno per la vita."}
MultiLanguageSpellData['it'][168291] = {name = "Zanna Intagliata dei Lupi Bianchi", additional_info = "2 s di lancio 5\n[q]Come parte del rito di passaggio alla maggiore età, ogni Orco dei Lupi Bianchi deve uccidere un cinghiale del gelo e incidere sulla sua zanna più grande la genealogia della propria famiglia. Le tradizioni delle famiglie sono tenute in grande considerazione dal Clan Lupi Bianchi: per questo motivo i cinghiali del gelo più grossi vengono cacciati ogni stagione per preservare il lignaggio del clan."}
MultiLanguageSpellData['it'][168292] = {name = "Racchette da Neve in Pelle di Lupo", additional_info = "2 s di lancio 5\n[q]A causa della scarsa vegetazione presente nel gelido deserto della Landa di Fuocogelo, per sopravvivere i Lupi Bianchi hanno sempre dovuto fare affidamento sulle proprie doti di caccia. Queste racchette da neve, costruite con le ossa e le pelli dei lupi, permettono ai cacciatori di non sprofondare nella neve mentre inseguono la preda."}
MultiLanguageSpellData['it'][168293] = {name = "Tamburi dell'Oratore della Guerra", additional_info = "2 s di lancio 5\n[q]Facendo leva sulla paura e sul timore per sbaragliare i nemici, i Cantaguerra guadagnarono il loro nome grazie ai loro temibili urli di battaglia e fragorosi tamburi. Questi macabri tamburi in particolare sono stati costruiti con della pelle di talbuk tirata su quelli che sembrano teschi di Ogre, in celebrazione della libertà del clan dall'impero degli Ogre."}
MultiLanguageSpellData['it'][168294] = {name = "Rombo Urlante", additional_info = "2 s di lancio 5\n[q]Il rombo consiste in un pezzo di legno rigido, lungo circa un braccio, legato a una lunga corda; viene fatto ruotare sopra la testa per generare un ronzio molto forte, udibile anche a grandi distanze. Questo esemplare è stato intagliato dai Cantaguerra per emettere un fischio estremamente acuto, diversamente del suono basso generato dalla maggior parte degli strumenti usati dagli altri clan."}
MultiLanguageSpellData['it'][168295] = {name = "Picca Cerimoniale dei Cantaguerra", additional_info = "2 s di lancio 5\n[q]I Cavalcalupi del Clan Cantaguerra sono sempre in movimento. Negli accampamenti, le tende delle varie famiglie sono contrassegnate da una lunga picca conficcata nel terreno, spesso adornata con i teschi dei nemici sconfitti. Questo pezzo è di oltre cent'anni fa e reca i nomi di diverse battaglie importanti."}
MultiLanguageSpellData['it'][168296] = {name = "Martello da Metallurgico", additional_info = "2 s di lancio 5\n[q]Nonostante il gran numero di ammaccature e graffi, l'iconografia tipica del Clan Roccianera incisa su questo martello è ben visibile. È per questo che il clan degli Orchi Roccianera, il primo a padroneggiare la forgiatura dei metalli, preferisce impugnare armi contundenti in battaglia per onorare i propri antenati."}
MultiLanguageSpellData['it'][168297] = {name = "Mantice Elementale", additional_info = "2 s di lancio 5\n[q]Il Clan Roccianera originariamente utilizzava gli inferni elementali naturali di Draenor per modellare e rinforzare il minerale a cui aveva dato il proprio nome. Uno Sciamano poteva utilizzare questi mantici per canalizzare il potere di uno spirito di fuoco verso un altoforno, permettendo ai Roccianera di creare delle forge in qualsiasi luogo."}
MultiLanguageSpellData['it'][168298] = {name = "Rasoio dei Roccianera", additional_info = "2 s di lancio 5\n[q]Gli Orchi maschi del Clan Roccianera non si tagliano i capelli fino alla maggiore età, momento in cui si rasano e viene stabilito il loro ruolo all'interno di una società rigidamente regolamentata. Questo antico rasoio a serramanico è stato forgiato a Roccianera ed è adornato di pietre preziose, quindi probabilmente è stato usato da una famiglia importante per l'iniziazione di diverse generazioni."}
MultiLanguageSpellData['it'][168299] = {name = "Ascia da Taglio Piombata", additional_info = "2 s di lancio 5\n[q]Prendendo alla lettera il proprio nome, i guerrieri del Clan Manomozza maciullano ritualisticamente la propria mano prima di amputarsela. Il moncone viene poi cauterizzato e la mano sostituita con una delle numerose armi a disposizione. Questa lama, che ricorda una mannaia da macellaio, è stata pesantemente piombata per assicurare un taglio preciso del polso."}
MultiLanguageSpellData['it'][168300] = {name = "Pugnale Uncinato", additional_info = "2 s di lancio 5\n[q]I Manomozza celebrano le vittorie in battaglia con ritualistiche automutilazioni. I loro guerrieri più forti sono ricoperti di cicatrici e scarnificazioni, e col passare del tempo diventa sempre più difficile identificare quali siano stati inflitti dai nemici e quali dagli stessi Orchi in segno di trionfo."}
MultiLanguageSpellData['it'][168301] = {name = "Amo da Pesca Uncinato", additional_info = "2 s di lancio 5\n[q]Questo strumento da pesca lungo un braccio è più simile a un'alabarda che a un normale amo da pesca. Puoi solo immaginare le dimensioni delle prede catturate con questo amo, e non stupisce che gli Orchi preferiscano cacciare sulla terraferma."}
MultiLanguageSpellData['it'][168302] = {name = "Occhio Calcificato in un Vaso", additional_info = "2 s di lancio 5\n[q]Questo occhio ben preservato dev'essere appartenuto a un Capoclan dei Guerci Insanguinati. Ogni nuovo Capoclan deve affrontare una visione sciamanica in cui si strappa un occhio per poter assistere alla propria morte. Impossibile immaginare a quale atroce destino abbia dovuto assistere quest'occhio."}
MultiLanguageSpellData['it'][168303] = {name = "Aghi da Tatuaggio Cerimoniali", additional_info = "2 s di lancio 5\n[q]Questi aghi sono fatti con le ossa prelevate dai nemici uccisi e finemente lavorate fino a farle diventare estremamente appuntite. I mistici del Clan Torvaluna spesso iscrivono rune segrete sulla propria pelle per poter comunicare più facilmente con i propri antenati e gli spiriti elementali."}
MultiLanguageSpellData['it'][168304] = {name = "Idolo d'Avorio Incrinato", additional_info = "2 s di lancio 5\n[q]Questo idolo nero come la notte è un esempio dell'adorazione del Vuoto, un tempo praticata dagli anziani del Clan Torvaluna e ora bandita. Rozzamente e febbrilmente ricavato dalla zanna di un enorme elekk, l'idolo è stato poi colorato di nero e intagliato con trame frastagliate e turbinanti."}
MultiLanguageSpellData['it'][168305] = {name = "Talismano Ancestrale", additional_info = "2 s di lancio 5\n[q]Quando è necessario fare una scelta importante, gli Sciamani del Clan Torvaluna consultano sempre gli spiriti delle generazioni passate. Talismani e altre reliquie importanti per un antenato mentre era in vita forniscono agli Sciamani una connessione più chiara quando cercano di contattarlo nell'oltretomba."}
MultiLanguageSpellData['it'][168306] = {name = "Fiasca di Grasso Incendiario", additional_info = "2 s di lancio 5\n[q]Appiccicosa, puzzolente e altamente infiammabile, la sostanza in questo piccolo contenitore viene generosamente applicata sulle spade e sulle asce dai membri del Clan Lame Ardenti prima della battaglia. Anche se alcuni guerrieri scelgono di dar fuoco alle armi prima dello scontro, la maggior parte di loro lascia che siano le scintille della battaglia a far scaturire le fiamme."}
MultiLanguageSpellData['it'][168307] = {name = "Collana con Dente di Gronn", additional_info = "2 s di lancio 5\n[q]Gli Spaccatuono sono i più grandi esperti di caccia grossa di tutta Draenor. Per secoli hanno sfruttato cavalcature e assalti coordinati per uccidere grosse prede o addirittura i Gronn. Il loro clan prende il nome da un antico Capoclan che uccise da solo un potente Gronn presso la Vetta del Tuono."}
MultiLanguageSpellData['it'][168308] = {name = "Profezia dell'Apocalisse", additional_info = "2 s di lancio 5\n[q]Questa tavoletta parla della \"fine dei tempi\". Da quanto si riesce a decifrare, le incisioni grezze di più autori parlano di almeno sette versioni diverse e talvolta contrastanti di una sorta di resa dei conti finale per tutti gli abitanti di Draenor. Stranamente, vi è disegnata anche l'icona di un martello fiammeggiante: è questa l'antica origine del Clan Martello del Crepuscolo?"}
MultiLanguageSpellData['it'][168309] = {name = "Masso di Successione dei Mazzapietra", additional_info = "2 s di lancio 5\n[q]I Capoclan guidano piccole bande di Ogre col pugno di ferro, e devono sempre essere pronti ad affrontare gli sfidanti interessati a raggiungere il potere. Il Clan Mazzapietra è particolarmente rinomato per i frequenti cambi al comando: a giudicare dai numerosi strati di sangue presenti su questo masso, sembra sia stato utilizzato come strumento per deporre numerosi Capoclan Mazzapietra."}
MultiLanguageSpellData['it'][168310] = {name = "Manette in Pietra", additional_info = "2 s di lancio 5\n[q]Invece di utilizzare ganci e lucchetti, gli Ogre tengono prigionieri i propri schiavi utilizzando duri cerchi di pietra. Secoli di manipolazione degli elementi della terra permettono loro di stringere a loro piacimento le manette attorno alle caviglie, ai polsi o al collo di uno schiavo."}
MultiLanguageSpellData['it'][168311] = {name = "Statuetta di Ogre", additional_info = "2 s di lancio 5\n[q]Esprimendo con la scultura ciò che la maggior parte degli Ogre fa fatica a comunicare con le parole, questa statua racchiude l'elemento fisico a loro più caro: le dimensioni. Il mammuceronte tenuto sopra la testa dell'Ogre rappresenta la forza, mentre l'abbondante giro vita simboleggia il benessere fisico."}
MultiLanguageSpellData['it'][168312] = {name = "Pittogramma Inciso", additional_info = "2 s di lancio 5\n[q]Mentre la parola scritta veniva usata soprattutto dalle alte sfere della società degli Ogre imperiali, di tanto in tanto un Ogre ordinario cercava di scrivere di sua mano una storia immortale. Questo pittogramma sembra raccontare la storia di un'esperienza culinaria particolarmente angosciante."}
MultiLanguageSpellData['it'][168313] = {name = "Scudo del Gladiatore", additional_info = "2 s di lancio 5\n[q]I disaccordi tra gli Ogre generalmente finiscono in violenza. Durante le prime decadi dell'Era dell'Ordine, un astuto Capoclan ordinò di risolvere le dispute tra i membri del suo clan con degli scontri tra schiavi. La mortalità tra gli Ogre precipitò significativamente, dando inizio a un'era d'oro di espansione."}
MultiLanguageSpellData['it'][168314] = {name = "Mortaio e Pestello", additional_info = "2 s di lancio 5\n[q]Desiderosi di mostrare la propria prestanza fisica, gli Ogre disdegnano gli indumenti che coprono eccessivamente la pelle. Per sembrare più pericolosi ai nemici, adornano i propri corpi con pitture di guerra create con questi strumenti. Questo particolare mortaio e pestello presentano tracce gialle, colore storicamente associato al Clan Rocciadura.\nSi vincola alla raccolta\n[q2]Usa: Imballi con attenzione il Manufatto Restaurato.\n[q]\"I dettagli del Manufatto sono registrati nel tuo Diario di Archeologia, nella scheda dei Manufatti Completati.\""}
MultiLanguageSpellData['it'][168315] = {name = "Occhio di Har'gunn il Guercio", additional_info = "2 s di lancio 5\n[q]Benché la maggior parte degli Ogre nasca con due occhi, un paio di individui ogni generazione regredisce e nasce con un occhio solo. La maggior parte dei clan ritiene che questi individui siano eccezionali e destinati a realizzare grandi cose. Uno sfortunato Mago Ogre perse il suo unico occhio in un duello e l'orbita vuota venne riempita con questa pietra delle dimensioni di un pugno. Così facendo, scoprì che il nuovo occhio possedeva particolari proprietà magiche."}
MultiLanguageSpellData['it'][168316] = {name = "Dentiera in Pietra", additional_info = "2 s di lancio 5\n[q]Gli Ogre sono molto diretti in combattimento e spesso soffrono ferite pari a quelle inferte, facendo affidamento unicamente sulla forza e la resistenza per ottenere la vittoria. Questa dentiera seghettata è la prova che almeno un Ogre ha perso tutti i suoi denti ed è sopravvissuto per combattere nuovamente."}
MultiLanguageSpellData['it'][168317] = {name = "Sella per Rylak", additional_info = "2 s di lancio 5\n[q]Un brillante Ogre un tempo pensò che cavalcare un rylak avrebbe reso più veloci gli spostamenti rispetto a camminare o sfruttare animali da soma. Creata in modo rozzo sfruttando del cuoio resistente e un eccessivo numero di nodi, questa sella è sufficientemente grande per far accomodare un Ogre. Purtroppo, potrebbe essere utilizzata solo su un rylak delle dimensioni di una collina, e probabilmente è per questo che nessuno ha mai visto un Ogre volare."}
MultiLanguageSpellData['it'][168318] = {name = "Stele con Decreto Imperiale", additional_info = "2 s di lancio 5\n[q]I frammenti assemblati di questa stele di pietra indicano che si trovava a Talador diverse centinaia d'anni prima dell'arrivo dei Draenei. Vi è inciso un decreto imperiale degli Ogre: radere al suolo numerosi insediamenti di Orchi come rappresaglia per alcune incursioni di ribelli contro le carovane di schiavi di Gorian. Gli ordini furono probabilmente eseguiti, dal momento che gli insediamenti non esistono più, e la stele è stata eretta per commemorare l'atroce carneficina."}
MultiLanguageSpellData['it'][168319] = {name = "[q3]Anello da Alluce del Re Stregone", additional_info = "2 s di lancio 10\n[q]Gli Orchi imperiali custodivano gelosamente i segreti della magia, al fine di mantenere il proprio status privilegiato. I più ricchi tra loro si adornavano con potenti gioielli magici e altri manufatti e monili.\n[q3]Anello da Alluce del Re Stregone\n[q7]Si vincola alla Brigata\nCollo\n+3 Intelletto\n+4 Tempra\n[q2]+ 3 Critico\n[q2]+ 2 Celerità\n35"}
MultiLanguageSpellData['it'][168320] = {name = "[q3]Fortemaglio del Capoclan dei Fortemaglio", additional_info = "2 s di lancio 10\n[q]La prima grande innovazione tecnologica nella società degli Ogre fu l'idea di attaccare una roccia alla fine di un grosso bastone per colpire più forte i nemici, sistema più efficace di una semplice roccia in mano. Lo scisma nella società degli Ogre provocato da quest'innovazione si è concluso solo con la divisione dell'ormai dimenticata tribù originaria nei Clan Fortemaglio e Rocciadura.\n[q3]Fortemaglio del Capoclan dei Fortemaglio\n[q7]Si vincola alla Brigata\nDue mani Mazza\n10 - 14 Danni Velocità 3.60\n(3.3 danni per secondo)\n+5 Forza\n+7 Tempra\n[q2]+ 5 Critico\n[q2]+ 3 Celerità\nIntegrità 100 / 100\n35"}
MultiLanguageSpellData['it'][168321] = {name = "Acchiappasogni", additional_info = "2 s di lancio 5\n[q]Quando Terokk tornò dall'esilio, era ferito e incapace di volare. Le voci della sua maledizione si diffusero tra gli Arakkoa, facendo nascere superstizioni e credenze mistiche. Gli acchiappasogni divennero una delle icone protettrici più usate: gli Arakkoa credevano che la maledizione potesse impigliarsi nelle loro trame e svanire alla luce del mattino."}
MultiLanguageSpellData['it'][168322] = {name = "Urna Funeraria", additional_info = "2 s di lancio 5\n[q]Dopo la morte, tutti gli Arakkoa cercano di raggiungere la Dea del Sole Rukhmar nei cieli sopra Draenor, quindi la cremazione è di gran lunga preferibile alla sepoltura. Alcuni vogliono che le proprie ceneri vengano disperse in alto nei cieli, altri che siano raccolte in urne decorate conservate nelle cripte."}
MultiLanguageSpellData['it'][168323] = {name = "Pergamene con Decreti", additional_info = "2 s di lancio 5\n[q]Le scritte incomplete sembrano indicare un decreto riguardante una sorta di legge marziale, e raccomandano di prestare attenzione ai segni della maledizione tra vicini e amici."}
MultiLanguageSpellData['it'][168324] = {name = "Globo Solare", additional_info = "2 s di lancio 5\n[q]Al centro del culto degli Alti Arakkoa vi è la devozione per Rukhmar e per il sole. Centinaia di globi solari sono sparsi per la Vetta dei Cieli e gettano una luce infinita, così che nessun Arakkoa possa restare senza il calore del sole, anche nelle giornate fredde e nuvolose."}
MultiLanguageSpellData['it'][168325] = {name = "Meridiana", additional_info = "2 s di lancio 5\n[q]Questo strumento delicatamente inciso, se posizionato correttamente, agisce sia come una meridiana che come un calendario stagionale degli Arakkoa. La base dello strumento è coperta di segnalazioni sugli eventi celesti, la maggior parte delle quali è accompagnata da spaventosi avvertimenti. È interessante notare che il dispositivo sembra aver misteriosamente previsto l'arrivo dei Draenei un secolo prima che avvenisse."}
MultiLanguageSpellData['it'][168326] = {name = "Maschera da Sacerdote dell'Artiglio", additional_info = "2 s di lancio 5\n[q]Credendo di essere stati abbandonati dal sole, durante le ore diurne gli Arakkoa maledetti preferiscono nascondersi nelle foreste o sotto le tende. I Sacerdoti dell'Artiglio si spingono oltre, non mostrando i propri volti al sole, nascondendoli dietro maschere rituali che fungono da strumento per la comunicazione con Anzu."}
MultiLanguageSpellData['it'][168327] = {name = "Acchiappasogni degli Esiliati", additional_info = "2 s di lancio 5\n[q]Gli Esiliati Arakkoa usano gli acchiappasogni non per scongiurare la Maledizione di Sethe, ma per catturare e raccogliere un po' dell'essenza dei loro dei perduti. Voci dicono con insistenza che una massa crescente di energia vorticosa sia sepolta sotto Skettis, e sussurrano promesse di potere a chiunque voglia ascoltarle..."}
MultiLanguageSpellData['it'][168328] = {name = "Cristallo Apexis", additional_info = "2 s di lancio 5\n[q]Sparsi nella più antica delle rovine su Draenor vi sono frammenti e voci sulla civiltà Apexis, che raggiunse la massima potenza durante l'Era dell'Ordine e poi improvvisamente svanì. L'arrivo dell'Orda di Ferro ha scatenato una ricerca segreta e pressante dei manufatti degli Apexis da parte dei Proseliti."}
MultiLanguageSpellData['it'][168329] = {name = "Geroglifico Apexis", additional_info = "2 s di lancio 5\n[q]Incredibilmente fragile e antica, questa tavoletta di pietra presenta delle incisioni che descrivono vagamente un motore di una potenza incredibile, che sembra sfrutti la potenza del sole."}
MultiLanguageSpellData['it'][168330] = {name = "Pergamena Apexis", additional_info = "2 s di lancio 5\n[q]Questa strana e malconcia custodia, sigillata dalla corrosione, racchiude al suo interno una pergamena a malapena leggibile se non in seguito a un accurato esame. Sembra trattarsi di un progetto per un magnifico \"Tempio nel Cielo\", scritto in un'antica calligrafia. Non è chiaro se la splendida struttura sia effettivamente stata costruita o meno."}
MultiLanguageSpellData['it'][168331] = {name = "[q3]Spezzabecchi di Terokk", additional_info = "2 s di lancio 10\n[q]Disdegnando le armi tradizionali degli Arakkoa, Terokk impugnava questa clava come simbolo della sua caduta da re a esiliato. Per secoli si susseguirono voci che dicevano che, invece di tagliare le ali come prevedevano le punizioni tradizionali, Terokk semplicemente frantumasse i becchi di coloro che osavano opporglisi.\n[q3]Spezzabecchi di Terokk\n[q7]Si vincola alla Brigata\nUna mano Mazza\n5 - 7 Danni Velocità 2.60\n(2.3 danni per secondo)\n+2 [Agilità o Forza]+3 Tempra\n[q2]+ 2 Critico\n[q2]+ 2 Maestria\nIntegrità 90 / 90\n35"}
