MultiLanguageSpellData['it'][168347] = {name = "Marchio della Morte", additional_info = "Portata di 300 m\nIstantaneo\n[q]Manonera marchia a morte un bersaglio. Dopo 8 sec, Manonera usa l'abilità Lancio Impalante sul bersaglio. Lancio Impalante impatta sul primo oggetto colpito. La velocità di movimento dei bersagli marchiati aumenta del 0%."}
