MultiLanguageSpellData['it'][168349] = {name = "Ben Nutrito", additional_info = "Ben Nutrito Livello 80\n[q0][Item Effect]Istantaneo\n[q]Mangiare questo piatto degli Arakkoa aumenta l'indice di versatilità di 14 per 30 min.\n\n Il beneficio ha effetto solo nelle Rovine di Skettis presso le Guglie di Arakk."}
MultiLanguageSpellData['it'][168350] = {name = "Impatto delle Fiamme", additional_info = "Portata di 30 m\n{1 s di lancio} {4 s di recupero}\n[q]Soffia fuoco frontalmente, incendiando il terreno per 15 sec. I personaggi all'interno dell'area d'effetto subiscono danni da fuoco ogni secondo."}
