MultiLanguageSpellData['it'][168835] = {name = "[q2]Tessuto di Malastoffa", additional_info = "1.5 s di lancio 1 giorno di recupero\nReagenti:\nPelliccia Splendida (20), Acchiappamosche di Gorgrond (10)\n[q]Produce 8 pezzi di Tessuto di Malastoffa. In base alla competenza in Sartoria, può creare tessuti aggiuntivi.\n\n È possibile creare anche dell'Iperacqua e dell'Iperaria.\n\n Il tempo di recupero si reimposta quotidianamente.\nMercante:\nChristopher Macdonald\nOggetto:\nSartoria di Draenor\nCosto:\n100\nZona:\nCalaluna\n\nMercante:\nSteven Cochrane\nOggetto:\nSartoria di Draenor\nCosto:\n100\nZona:\nAshran\n\n[q2]Tessuto di Malastoffa\nSi vincola alla raccolta\nReagente d'artigianato\n[q]\"Una pelliccia trasformata in un fine tessuto. Materiale base per la Sartoria su Draenor.\""}
MultiLanguageSpellData['it'][168836] = {name = "[q3]Ricamo di Malastoffa", additional_info = "1.5 s di lancio\nSenza professione:\nRichiede l'Atelier di Sartoria di livello 2.\nReagenti:\nPelliccia Splendida (30)\nMercante:\nPetir Mareastrale\nZona:\nLancia da Guerra\nCosto:\n1\n\n[q3]Ricamo di Malastoffa\n[q2]Usa: Modifica gli attributi secondari di un equipaggiamento creato con Sartoria di Draenor di livello 45 o inferiore.\n35\n[q]\"È possibile reindirizzare il potere della Malastoffa grazie ai ricami.\""}
