MultiLanguageSpellData['it'][171206] = {name = "Apprendimento", additional_info = "[q0][Item Effect]3 s di lancio\n[q]Fornisce il progetto necessario per costruire la Miniera di Rocciafredda nella tua Guarnigione.\n\n Level 1\nPermette di raccogliere Pietre Draenoriane dalle vene minerarie di Draenor. La Pietra Draenoriana può essere sfruttata per assegnare incarichi di lavoro relativi ai minerali di Draenor.\n\n Level 2\nPermette ai seguaci con la caratteristica Estrazione di lavorare in questo edificio, fornendo un bonus unico. Inoltre, apre una nuova galleria, dando accesso ad altre vene minerarie, e permette la gestione di 14 incarichi di lavoro alla volta.\n\n Level 3\nUn'altra galleria mineraria fornisce l'accesso a ricche vene minerarie. Inoltre, le guardie della Guarnigione pattugliano la miniera, proteggendola dai Goren ostili. Permette la gestione di 21 incarichi di lavoro alla volta."}
MultiLanguageSpellData['it'][171208] = {name = "Apprendimento", additional_info = "3 s di lancio\n[q]Fornisce il progetto necessario per potenziare la Miniera di Rocciafredda della tua Guarnigione al livello 2.\n\n Level 1\nPermette di raccogliere Pietre Draenoriane dalle vene minerarie di Draenor. La Pietra Draenoriana può essere sfruttata per assegnare incarichi di lavoro relativi ai minerali di Draenor.\n\n Level 2\nPermette ai seguaci con la caratteristica Estrazione di lavorare in questo edificio, fornendo un bonus unico. Inoltre, apre una nuova galleria, dando accesso ad altre vene minerarie, e permette la gestione di 14 incarichi di lavoro alla volta.\n\n Level 3\nUn'altra galleria mineraria fornisce l'accesso a ricche vene minerarie. Inoltre, le guardie della Guarnigione pattugliano la miniera, proteggendola dai Goren ostili. Permette la gestione di 21 incarichi di lavoro alla volta."}
MultiLanguageSpellData['it'][171209] = {name = "Caricamento Cassa", additional_info = nil}
MultiLanguageSpellData['it'][171210] = {name = "Apprendimento", additional_info = "[q0][Item Effect]3 s di lancio\n[q]Fornisce il progetto necessario per potenziare la Miniera di Rocciafredda della tua Guarnigione al livello 2.\n\n Level 1\nPermette di raccogliere Pietre Draenoriane dalle vene minerarie di Draenor. La Pietra Draenoriana può essere sfruttata per assegnare incarichi di lavoro relativi ai minerali di Draenor.\n\n Level 2\nPermette ai seguaci con la caratteristica Estrazione di lavorare in questo edificio, fornendo un bonus unico. Inoltre, apre una nuova galleria, dando accesso ad altre vene minerarie, e permette la gestione di 14 incarichi di lavoro alla volta.\n\n Level 3\nUn'altra galleria mineraria fornisce l'accesso a ricche vene minerarie. Inoltre, le guardie della Guarnigione pattugliano la miniera, proteggendola dai Goren ostili. Permette la gestione di 21 incarichi di lavoro alla volta."}
MultiLanguageSpellData['it'][171211] = {name = "Apprendimento", additional_info = "[q0][Item Effect]3 s di lancio\n[q]Fornisce il progetto necessario per potenziare la Miniera di Rocciafredda della tua Guarnigione al livello 3.\n\n Level 1\nPermette di raccogliere Pietre Draenoriane dalle vene minerarie di Draenor. La Pietra Draenoriana può essere sfruttata per assegnare incarichi di lavoro relativi ai minerali di Draenor.\n\n Level 2\nPermette ai seguaci con la caratteristica Estrazione di lavorare in questo edificio, fornendo un bonus unico. Inoltre, apre una nuova galleria, dando accesso ad altre vene minerarie, e permette la gestione di 14 incarichi di lavoro alla volta.\n\n Level 3\nUn'altra galleria mineraria fornisce l'accesso a ricche vene minerarie. Inoltre, le guardie della Guarnigione pattugliano la miniera, proteggendola dai Goren ostili. Permette la gestione di 21 incarichi di lavoro alla volta."}
MultiLanguageSpellData['it'][171212] = {name = "Apprendimento", additional_info = "[q0][Item Effect]3 s di lancio\n[q]Fornisce il progetto necessario per costruire una Fucina di Guerra nella tua Guarnigione.\n\n Level 1\nRaddoppia le probabilità di ottenere un Potenziamento Bonus raro o epico come ricompensa di missione e ne migliora la qualità. Permette la raccolta di pezzi di armatura dai clan degli Orchi di Draenor da utilizzare per la trasmogrificazione.\n\n Level 2\nPermette di assegnare incarichi di lavoro per la realizzazione di armi e armature dei seguaci in cambio di Risorse per la Guarnigione. Sblocca anche nuovi oggetti per la trasmogrificazione.\n\n Level 3\nFornisce gratuitamente uno dei tre Sigilli del Destino Inevitabile per i tiri bonus in un'incursione una volta alla settimana."}
