MultiLanguageSpellData['it'][171221] = {name = "Seguace: Difensore Illona", additional_info = "Istantaneo\n[q]Illona aveva sempre sognato di unirsi, un giorno, all'antico ordine degli Auchenai. Quando l'Esarca Maladaar ha invocato l'aiuto di qualsiasi Draenei disponibile e capace, Illona ha preso l'armatura di suo nonno ed è partita incontro al proprio destino."}
