MultiLanguageSpellData['it'][171231] = {name = "Masticazione Penetrante", additional_info = "Portata di 25 m\n1 s di lancio\n[q]Morde tutti i nemici frontali entro 15 m, infliggendo danni fisici a tutti i personaggi che finiscono nelle sue fauci.\n Le vittime dell'attacco sono contagiate da Masticazione Penetrante, aumentando i danni subiti da ulteriori Masticazioni Penetranti del 10% per accumulo."}
MultiLanguageSpellData['it'][171233] = {name = "Soffio Persistente", additional_info = "Portata di 30 m\n{2 s di lancio} {15 s di recupero}\n[q]Esala dei vapori nocivi, infliggendo danni da natura a tutti i personaggi frontali entro 30 m.\n I vapori si allontanano dall'incantatore, infliggendo danni da natura a tutti i personaggi sulla loro traiettoria ed emettendo gas tossici che infliggono danni da natura a tutti i personaggi nell'area d'effetto."}
