MultiLanguageSpellData['it'][171616] = {name = "Pestacolli Mantosfolto", additional_info = "1.5 s di lancio\n[q]Evoca e congeda un Pestacolli Mantosfolto.\n[q]\"Piccole scanalature ricoprono gli zoccoli di questo mammuceronte, permettendogli di inerpicarsi in sicurezza le zone montuose in cerca di cibo.\"\nMercante:\nCommerciante Araanda\nZona:\nCalaluna\nCosto:\n20.000\n\nMercante:\nCommerciante Darakk\nZona:\nRocciafredda\nCosto:\n20.000"}
MultiLanguageSpellData['it'][171617] = {name = "Zoccolofreddo Addestrato", additional_info = "1.5 s di lancio\n[q]Evoca e congeda uno Zoccolofreddo Addestrato.\n[q]\"Solo provando questa cavalcatura hai compreso davvero quanto Draenor ti stesse mettendo alla prova. Il pelo di mammuceronte si impiglia dappertutto!\"\nFonte:\nScuderia della Guarnigione"}
MultiLanguageSpellData['it'][171618] = {name = "Mammuceronte Pelleferrea Antico", additional_info = "1.5 s di lancio\n[q]Evoca e congeda un Mammuceronte Pelleferrea Antico."}
MultiLanguageSpellData['it'][171619] = {name = "Zoccolofreddo della Tundra", additional_info = "1.5 s di lancio\n[q]Evoca e congeda uno Zoccolofreddo della Tundra.\n[q]\"Uno strato di pelo traslucido ricopre la sua pelle indurita, fornendogli una perfetta protezione negli ambienti più freddi.\"\nBottino:\nVendetta, Graffiamorte, Pugnocupo, Rovina Cingolata\nZona:\nGiungla di Tanaan"}
MultiLanguageSpellData['it'][171620] = {name = "Zoccolorosso Adulto", additional_info = "1.5 s di lancio\n[q]Evoca e congeda uno Zoccolorosso Adulto.\n[q]\"I membri del Clan Cantaguerra hanno a lungo dato la caccia a questi mammuceronti per poterli usare in battaglia.\"\nBottino:\nNakk il Tuonatore\nZona:\nNagrand"}
MultiLanguageSpellData['it'][171621] = {name = "Zoccoloferreo Distruttore", additional_info = "1.5 s di lancio\n[q]Evoca e congeda uno Zoccoloferreo Distruttore.\n[q]\"Si dice che Manonera stesso abbia progettato gli armamenti usati sui mammuceronti da guerra dell'Orda di Ferro.\"\nBottino:\nManonera\nZona:\nFonderia dei Roccianera (Mitica)"}
MultiLanguageSpellData['it'][171622] = {name = "Calcaradure Chiazzato", additional_info = "1.5 s di lancio\n[q]Evoca e congeda un Calcaradure Chiazzato.\n[q]\"La lunga proboscide degli elekk permette loro di sentire l'odore del cibo, avvertire i pericoli e rubare le merendine dalle sacche degli avventurieri senza che se ne accorgano.\"\nBottino:\nLuk'hok\nZona:\nNagrand"}
MultiLanguageSpellData['it'][171623] = {name = "Calcaradure Addestrato", additional_info = "1.5 s di lancio\n[q]Evoca e congeda un Calcaradure Addestrato.\n[q]\"I Draenei hanno perfezionato l'allevamento degli elekk molto tempo fa, adornando le creature con cristalli infusi di Luce per renderle più docili.\"\nMissione:\nScuderia della Guarnigione"}
MultiLanguageSpellData['it'][171624] = {name = "Zannaperlacea Mantombroso", additional_info = "1.5 s di lancio\n[q]Evoca e congeda uno Zannaperlacea Mantombroso.\n[q]\"Alcune leggende narrano che i Draenei si avvicinarono agli elekk per la prima volta dopo che uno di essi salvò un esploratore ferito da un branco di Sporoidi famelici.\"\nBottino:\nTesoro Dimenticato dell'Invasore"}
MultiLanguageSpellData['it'][171625] = {name = "Scagliadura Polveroso", additional_info = "1.5 s di lancio\nFazione: Alleanza\n[q]Evoca e congeda uno Scagliadura Polveroso.\n[q]\"Da quando hai ottenuto questa cavalcatura, hai iniziato a essere perseguitato nel sonno da una parata di elekk rosa.\"\nMercante:\nVendicatore Nuurem\nFazione:\nConcilio degli Esarchi - Osannato\nZona:\nScudo del Vento\nCosto:\n5.000\n+ 5.000"}
MultiLanguageSpellData['it'][171626] = {name = "Zannaferrea Corazzato", additional_info = "1.5 s di lancio\nFazione: Alleanza\n[q]Evoca e congeda uno Zannaferrea Corazzato.\n[q]\"Si vocifera che gli elekk non dimentichino mai nulla. Non c'è da stupirsi che disprezzino l'Orda di Ferro, se consideriamo i tormenti che gli Orchi hanno inflitto a queste bestie.\"\nMercante:\n\nFazione:\nProtettori Sha'tari - Osannato\nZona:\nEmporio della Guarnigione\nCosto:\n5.000\n+ 5.000"}
MultiLanguageSpellData['it'][171627] = {name = "Cinghiale da Guerra d'Acciaio Nero", additional_info = "1.5 s di lancio\n[q]Evoca e congeda un Cinghiale da Guerra d'Acciaio Nero.\n[q]\"Rifiuta di muoversi a meno che la sua testa non sia coperta da una bardatura pesante e piena di spuntoni di ferro. È una questione di orgoglio.\"\nImpresa:\nGloria dell'incursore di gilda di Draenor"}
MultiLanguageSpellData['it'][171628] = {name = "Cinghiale da Guerra Zannapietra", additional_info = "1.5 s di lancio\n[q]Evoca e congeda un Cinghiale da Guerra Zannapietra.\n[q]\"Per dipingere una parete grande non serve un pennello grande, ma un grande pennello.\"\nMercante:\nCommerciante Araanda\nZona:\nCalaluna\nCosto:\n10.000\n\nMercante:\nCommerciante Darakk\nZona:\nRocciafredda\nCosto:\n10.000"}
MultiLanguageSpellData['it'][171629] = {name = "Cinghiale del Gelo Corazzato", additional_info = "1.5 s di lancio\n[q]Evoca e congeda un Cinghiale del Gelo Corazzato.\n[q]\"Si nutre quasi esclusivamente di bacche congelate, anche se trova le creature di Azeroth altrettanto gustose.\"\nImpresa:\nAllevamento avanzato"}
MultiLanguageSpellData['it'][171630] = {name = "Mantospino Corazzato", additional_info = "1.5 s di lancio\n[q]Evoca e congeda un Mantospino Corazzato.\n[q]\"Non mangiare mai... MAI... costine in sua presenza.\"\nBottino:\nVendetta, Graffiamorte, Pugnocupo, Rovina Cingolata\nZona:\nGiungla di Tanaan"}
MultiLanguageSpellData['it'][171631] = {name = "Impresa", additional_info = "[q0][Item Effect]Istantaneo\n[q]Permette di mettere in mostra gli Stendardi di Gilda nella tua Guarnigione."}
MultiLanguageSpellData['it'][171632] = {name = "Cinghiale da Guerra delle Pianure Gelide", additional_info = "1.5 s di lancio\n[q]Evoca e congeda un Cinghiale da Guerra delle Pianure Gelide.\n[q]\"Se non avesse quel bellissimo anello per zanne non si sentirebbe a suo agio.\"\nImpresa:\nGloria dell'eroe di Draenor"}
MultiLanguageSpellData['it'][171633] = {name = "Cinghiospino Selvaggio", additional_info = "1.5 s di lancio\n[q]Evoca e congeda un Cinghiospino Selvaggio.\n[q]\"Se vuoi goderti una cavalcata spensierata ti conviene cercare un \"Cinghiodolce Felice\" o qualcosa del genere.\"\nMercante:\nZ'tenga il Camminatore\nZona:\nGiungla di Tanaan\nFazione:\nBracconieri Selvaggi - Onorato\nCosto:\n1.000"}
MultiLanguageSpellData['it'][171634] = {name = "Mantospino Addomesticato", additional_info = "1.5 s di lancio\n[q]Evoca e congeda un Mantospino Addomesticato.\n[q]\"Addomesticato\" non significa \"amichevole\". Ti conviene non esaurire i dolcetti.\nMercante:\nGazrix Sbloccaruote / Mimi Svitabulbi\nFazione:\nSocietà di Preservazione degli Spargifumo - Osannato\nZona:\nScudo del Vento / Lancia da Guerra\nCosto:\n5.000\n+ 5.000"}
MultiLanguageSpellData['it'][171635] = {name = "Grugnofreddo Gigante", additional_info = "1.5 s di lancio\n[q]Evoca e congeda un Grugnofreddo Gigante.\n[q]\"Il suo grugno non è semplicemente freddo, è umido. E non è certo piacevole avere il grugno umido di prima mattina.\"\nBottino:\nTesoro Dimenticato dell'Invasore"}
MultiLanguageSpellData['it'][171636] = {name = "Zannagrigia Maestoso", additional_info = "1.5 s di lancio\n[q]Evoca e congeda uno Zannagrigia Maestoso.\n[q]\"Cambia le zanne una volta all'anno e diventa estremamente timido fino a quando non gli sono ricresciute.\"\nBottino:\nGorok\nZona:\nLanda di Fuocogelo"}
MultiLanguageSpellData['it'][171637] = {name = "Zannapietra Addestrato", additional_info = "1.5 s di lancio\n[q]Evoca e congeda uno Zannapietra Addestrato.\n[q]\"Scrupolosamente addestrato a grugnire, trottare e travolgere i suoi nemici.\"\nMissione:\nScuderia della Guarnigione"}
MultiLanguageSpellData['it'][171638] = {name = "Sguazzafiumi Addestrato", additional_info = "1.5 s di lancio\n[q]Evoca e congeda uno Sguazzafiumi Addestrato.\n[q]\"Gli sguazzafiumi sono tra le creature più robuste di Draenor. Ciò si evince dalla loro elevata tempra e dal loro colore peculiare.\"\nMissione:\nScuderia della Guarnigione"}
