MultiLanguageSpellData['it'][171690] = {name = "[q2]Lingotto di Veracciaio", additional_info = "1.5 s di lancio 1 giorno di recupero\nStrumenti:\nMartello da Fabbro\nReagenti:\nMinerale di Puroferro (20), Minerale di Roccianera (10)\n[q]Produce 8 Lingotti di Veracciaio. In base alla competenza in Forgiatura, può creare lingotti aggiuntivi.\n\n È possibile creare anche dell'Iperfuoco e dell'Iperterra.\n\n Il tempo di recupero si reimposta quotidianamente.\nMercante:\nAuria Sognoferreo\nOggetto:\nForgiatura di Draenor\nCosto:\n100\nZona:\nCalaluna\n\nMercante:\nRoyce Barbagrande\nOggetto:\nForgiatura di Draenor\nCosto:\n100\nZona:\nAshran\n\n[q2]Lingotto di Veracciaio\nSi vincola alla raccolta\nReagente d'artigianato"}
MultiLanguageSpellData['it'][171691] = {name = "[q3]Elmo Infuocato", additional_info = "2 s di lancio\nStrumenti:\nMartello da Fabbro\nReagenti:\nMinerale di Roccianera (60)\nReagenti Facoltativi:\n[] (#31)\nMercante:\nAuria Sognoferreo\nOggetto:\nForgiatura di Draenor\nCosto:\n100\nZona:\nCalaluna\n\nMercante:\nRoyce Barbagrande\nOggetto:\nForgiatura di Draenor\nCosto:\n100\nZona:\nAshran\n\n[q3]Elmo Infuocato\nSi vincola all'equipaggiamento\nTesta Piastre\n13 Armatura\n+4 [Forza o Intelletto]+7 Tempra\nIntegrità 85 / 85\n39"}
