MultiLanguageSpellData['it'][171824] = {name = "Bestia dei Fiumi di Zaffiro", additional_info = "1.5 s di lancio\n[q]Evoca e congeda una Bestia dei Fiumi di Zaffiro.\n[q]\"Il colore di questo animale è azzurro come le acque cristalline dei fiumi di Draenor, il che lo rende quasi invisibile ai predatori acquatici.\"\nBottino:\nPellebraga\nZona:\nTalador"}
MultiLanguageSpellData['it'][171825] = {name = "Sguazzafiumi Pelomusco", additional_info = "1.5 s di lancio\n[q]Evoca e congeda uno Sguazzafiumi Pelomusco.\n[q]\"Aggressivi e territoriali, i Pelomusco sono conosciuti per nascondersi nella boscaglia sulla riva di qualche fiume e tendere agguati agli ignari passanti.\"\nMercante:\nCercatore dell'Alba Krek / Cercatore dell'Alba Alkset\nZona:\nScudo del Vento / Lancia da Guerra\nCosto:\n50.000\n+ 5.000"}
MultiLanguageSpellData['it'][171826] = {name = "Bestia dei Fiumi Dorsolimoso", additional_info = "1.5 s di lancio\n[q]Evoca e congeda una Bestia dei Fiumi Dorsolimoso.\n[q]\"Una caratteristica peluria cresce sotto le zampe dei Dorsolimoso, e consente loro di avere una maggiore stabilità nel fango o sui terreni scivolosi.\"\nMissione della Guarnigione:\nÈ solo una bestia dei fiumi"}
MultiLanguageSpellData['it'][171827] = {name = "Infernale del Fuoco Infernale", additional_info = "1.5 s di lancio\n[q]Evoca e congeda un Infernale del Fuoco Infernale.\n[q]\"Questa creatura di puro odio viene evocata dalle viscere del Fatuo, pronta a bruciare qualsiasi forma di vita incontri.\"\nBottino:\nGul'dan (Mitica)\nZona:\nRocca della Notte"}
MultiLanguageSpellData['it'][171828] = {name = "Falco delle Guglie Solare", additional_info = "1.5 s di lancio\n[q]Evoca e congeda un Falco delle Guglie Solare.\n[q]\"Guardare negli occhi questa mistica creatura è come perdersi nella luce del sole stesso. Mentre si cavalca, è consigliabile l'uso di occhiali protettivi.\"\nBottino:\nRukhmar"}
MultiLanguageSpellData['it'][171829] = {name = "Destriero Crinecupo", additional_info = "1.5 s di lancio\n[q]Evoca e congeda un Destriero Crinecupo.\n[q]\"I poeti Draenei hanno associato il colore di questo talbuk alle ombre gettate dagli alberi in una foresta al chiaro di luna.\"\nMercante:\nOratore dei Corvi Skeega / Saggio dell'Ombra Brakoss\nFazione:\nEsiliati Arakkoa - Osannato\nZona:\nScudo del Vento / Lancia da Guerra\nCosto:\n5.000\n+ 5.000"}
MultiLanguageSpellData['it'][171830] = {name = "Calcabrezza Agile", additional_info = "1.5 s di lancio\n[q]Evoca e congeda un Calcabrezza Agile.\n[q]\"I Draenei hanno fatto affidamento su questa cavalcatura, la più veloce tra i talbuk, per consegnare in tutta sicurezza i messaggi più importanti.\"\nBottino:\nCalcavie\nZona:\nValle di Torvaluna"}
MultiLanguageSpellData['it'][171831] = {name = "Mantoargenteo Addestrato", additional_info = "1.5 s di lancio\n[q]Evoca e congeda un Mantoargenteo Addestrato.\n[q]\"Acclamata per la sua intelligenza, questa razza di talbuk può essere addestrata per eseguire calci difensivi e incornate durante una battaglia.\"\nZona:\nScuderia della Guarnigione"}
MultiLanguageSpellData['it'][171832] = {name = "Stallone Calcabrezza", additional_info = "1.5 s di lancio\n[q]Evoca e congeda uno Stallone Calcabrezza.\n[q]\"Il suo colore rispecchia il suo temperamento: sanguinario, feroce e coraggioso.\"\nMercante:\nDazzerian\nFazione:\nLancia di Vol'jin - Osannato\nZona:\nLancia da Guerra\nCosto:\n5.000\n+ 5.000"}
MultiLanguageSpellData['it'][171833] = {name = "Brucaspine Pallido", additional_info = "1.5 s di lancio\n[q]Evoca e congeda un Brucaspine Pallido.\n[q]\"La dieta di questo talbuk è costituita unicamente da spine e rovi, il che rende questo animale tanto resistente dentro quanto fuori.\"\nMercante:\nPlagiamente Creaticus\nFazione:\nAvanguardia di Wrynn - Osannato\nZona:\nScudo del Vento\nCosto:\n5.000\n+ 5.000"}
MultiLanguageSpellData['it'][171834] = {name = "Montone da Guerra Malvagio", additional_info = "1.5 s di lancio\nFazione: Alleanza\n[q]Evoca e congeda un Montone da Guerra Malvagio.\n[q]\"Fino a quando non ti darà una testata sotto la cintura, non ti avrà riconosciuto come suo padrone.\"\nMercante:\nNecrosignore Sipe\nZona:\nRoccavento\nCosto:\n1"}
MultiLanguageSpellData['it'][171835] = {name = "Raptor da Guerra Malvagio", additional_info = "1.5 s di lancio\nFazione: Orda\n[q]Evoca e congeda un Raptor da Guerra Malvagio.\n[q]\"Giusto perché denti aguzzi e artigli affilati non erano abbastanza.\"\nMercante:\nGuardiamorte Netharian\nZona:\nOrgrimmar\nCosto:\n1"}
MultiLanguageSpellData['it'][171836] = {name = "Garn Fauciferree", additional_info = "1.5 s di lancio\n[q]Evoca e congeda un Garn Fauciferree.\n[q]\"Una volta un allevatore ha provato a mettere una placca di metallo nella bocca del suo Fauciferree. Ha dovuto aspettare tre giorni per riaverla indietro.\"\nBottino:\nTesoro Dimenticato dell'Invasore"}
MultiLanguageSpellData['it'][171837] = {name = "Zannafurente Cantaguerra", additional_info = "1.5 s di lancio\n[q]Evoca e congeda uno Zannafurente Cantaguerra.\n[q]\"Ha una volontà di ferro, ma diventa un tenerone se gli dai un osso di mammuceronte da sgranocchiare.\"\nBottino:\nVendetta, Graffiamorte, Pugnocupo, Rovina Cingolata\nZona:\nGiungla di Tanaan"}
MultiLanguageSpellData['it'][171838] = {name = "Lupo Bianco Corazzato", additional_info = "1.5 s di lancio\n[q]Evoca e congeda un Lupo Bianco Corazzato.\n[q]\"È addestrato per sopravvivere al rigido clima della Landa di Fuocogelo, quindi ama farsi coccolare come se non ci fosse un domani.\"\nImpresa:\nStalliere"}
MultiLanguageSpellData['it'][171839] = {name = "Lupo da Guerra Mantoferreo", additional_info = "1.5 s di lancio\nFazione: Orda\n[q]Evoca e congeda un Lupo da Guerra Mantoferreo.\n[q]\"Ha uno spuntone corazzato sulla coda: grattagli la pancia a tuo rischio e pericolo.\"\nMercante:\nKil'rip\nFazione:\nTeschio Ridente - Osannato\nZona:\nEmporio della Guarnigione dell'Orda\nCosto:\n5.000\n+ 5.000"}
MultiLanguageSpellData['it'][171840] = {name = "Infernale Fiammafredda", additional_info = "1.5 s di lancio\n[q]Evoca e congeda un Infernale Fiammafredda.\n[q]\"Le strane fiamme ghiacciate ti fanno sudare e rabbrividire allo stesso tempo.\"\nEmporio"}
MultiLanguageSpellData['it'][171841] = {name = "Ringhiatore Addestrato", additional_info = "1.5 s di lancio\n[q]Evoca e congeda un Ringhiatore Addestrato.\n[q]\"Estremamente tenero da cucciolo, ora lo è un po' meno.\"\nMissione:\nScuderia della Guarnigione"}
MultiLanguageSpellData['it'][171842] = {name = "Lupo Bianco Agile", additional_info = "1.5 s di lancio\nFazione: Orda\n[q]Evoca e congeda un Lupo Bianco Agile.\n[q]\"Tra le cime innevate di Fuocogelo, i lupi bianchi cacciano qualunque cosa abbiano a tiro. Solo il più veloce tra loro ha diritto a un buon pasto.\"\nMercante:\nBeska Zannarossa\nFazione:\nOrchi Lupi Bianchi - Osannato\nZona:\nLancia da Guerra\nCosto:\n5.000\n+ 5.000"}
MultiLanguageSpellData['it'][171843] = {name = "Metalupo Fumoso", additional_info = "1.5 s di lancio\n[q]Evoca e congeda un Metalupo Fumoso.\n[q]\"Si dice che viva principalmente nelle terre del nord. Odia i falò.\"\nBottino:\nTesoro Dimenticato dell'Invasore"}
MultiLanguageSpellData['it'][171844] = {name = "Metalupo Pelocinereo", additional_info = "1.5 s di lancio\n[q]Evoca e congeda un Metalupo Pelocinereo.\n[q]\"Più diffidenti rispetto agli altri metalupi, i Pelocinereo possono essere persuasi solo da qualcosa che considerino davvero speciale.\"\nProfessione:\nConceria"}
MultiLanguageSpellData['it'][171845] = {name = "Tritastrade da Guerra", additional_info = "1.5 s di lancio\nFazione: Orda\n[q]Evoca e congeda un Tritastrade da Guerra.\n[q]\"Noto anche come \"Falciaerba dei Goblin\", questo selvaggio marchingegno aggredisce i nemici come se fossero fili d'erba... pronti per essere falciati.\"\nImpresa:\nCategoria:\nProve di forza"}
MultiLanguageSpellData['it'][171846] = {name = "Monocingolo dei Campioni", additional_info = "1.5 s di lancio\nFazione: Alleanza\n[q]Evoca e congeda un Monocingolo dei Campioni.\n[q]\"Forgiato dal lavoro congiunto di Umani, Gnomi e Nani, questo capolavoro corazzato è stato progettato per ridurre rapidamente un Tauren in succulente costate.\"\nMercante:\nPaulie\nZona:\nRoccavento, Città Vecchia\nCosto:\n100.000"}
MultiLanguageSpellData['it'][171847] = {name = "Destriero Ardimanto", additional_info = "1.5 s di lancio\n[q]Evoca e congeda un Destriero Ardimanto.\n[q]\"Creato da Ragnaros stesso come dono per la figlia che non ha mai avuto.\"\nPromozione:\nRecluta un amico"}
MultiLanguageSpellData['it'][171848] = {name = "Yeti da Guerra dello Sfidante", additional_info = "1.5 s di lancio\n[q]Evoca e congeda uno Yeti da Guerra dello Sfidante.\n[q]\"Fortunatamente sono molto veloci e il loro terribile odore si diffonde solo dietro di loro.\"\nImpresa:\nSignore delle sfide: Argento"}
MultiLanguageSpellData['it'][171849] = {name = "Protogronn Mantosolare", additional_info = "1.5 s di lancio\n[q]Evoca e congeda un Protogronn Mantosolare.\n[q]\"Ama il sole. Odia tutto il resto.\"\nBottino:\nPugnograve\nZona:\nGorgrond"}
MultiLanguageSpellData['it'][171850] = {name = "Predatore di Llothien", additional_info = "1.5 s di lancio\n[q]Evoca e congeda un Predatore di Llothien.\n[q]\"Queste scaltre volpi, nonostante le dimensioni, possono correre sulle foglie secche senza emettere alcun suono.\"\nMissione:\nVolpin, l'Inafferrabile\nZona:\nSuramar"}
MultiLanguageSpellData['it'][171851] = {name = "Garn Urlocupo", additional_info = "1.5 s di lancio\n[q]Evoca e congeda un Garn Urlocupo.\n[q]\"I Garn sono i predatori più selvaggi di Draenor, e cacciano sempre in branco.\"\nBottino:\nNok-Karosh\nZona:\nLanda di Fuocogelo"}
