MultiLanguageSpellData['it'][172539] = {name = "Benda Antisettica", additional_info = "2 s di lancio\nReagenti:\nPelliccia Splendida (5)\n[q]Una formula per 4 pezzi. Il numero di pezzi può variare in base alla competenza in Primo Soccorso.\nProfessione:\nSartoria di Draenor (1)\n\n[q2]Usa: Cura di 2720 in 8 sec.\n35\n[q]\"Le proprietà curative del veleno dello Scorpione di Mare possono essere assorbite attraverso la pelle, ma è un processo lento.\""}
MultiLanguageSpellData['it'][172540] = {name = "Tonico Curativo", additional_info = "2 s di lancio\nReagenti:\nFiletto di Scorpione di Mare (10)\n[q]Crea 4 Tonici Curativi. Il numero di tonici può variare in base alla competenza.\nProfessione:\nAlchimia di Draenor (1)\n\n[q2]Usa: Rigenera 3400 salute. (5 Min Recupero)\n35\n[q]\"Se preparato in maniera corretta, il veleno dello Scorpione di Mare può rigenerare la salute.\""}
MultiLanguageSpellData['it'][172541] = {name = "Antiveleno di Acquanera", additional_info = "2 s di lancio\nReagenti:\nFiletto di Frustaliana Nera (10)\n[q]Crea 4 dosi di Antiveleno di Acquanera. Il numero di dosi può variare in base alla competenza.\nProfessione:\nAlchimia di Draenor (1)\n\n\n[q2]Usa: Cura i veleni fino al livello 49 e riduce la durata di nuovi effetti di veleno del 50% per 2 min. Funziona solo su Draenor. Non utilizzabile nelle istanze. (2 Min Recupero)\n35"}
MultiLanguageSpellData['it'][172542] = {name = "Olio di Ammonite del Fuoco", additional_info = "2 s di lancio\nReagenti:\nFiletto di Ammonite del Fuoco (10)\n[q]Crea 4 fiale di Olio di Ammonite del Fuoco. Il numero di fiale può variare in base alla competenza.\nProfessione:\nAlchimia di Draenor (1)\n\n\n[q2]Usa: Cura le malattie e riduce la durata di nuovi effetti di malattia del 50% per 2 min. Funziona solo su Draenor. Non utilizzabile nelle istanze. Inefficace oltre il livello 50. (2 Min Recupero)\n35\n[q]\"Brucia le infezioni senza danneggiare le vittime.\""}
