MultiLanguageSpellData['it'][178534] = {name = "Varco degli Stregoni", additional_info = "Portata illimitata\nIstantaneo\n[q]Gli Stregoni dell'Avamposto di Lancia da Guerra hanno attivato i Varchi degli Stregoni di Ashran, utili per spostarsi rapidamente nella zona.\n\n I Varchi degli Stregoni sono mostrati sulla mappa, nelle zone nord-ovest e sud-est di Ashran.\n\n Riportare a Nisstyr presso l'Avamposto di Lancia da Guerra 400 [Frammenti di Manufatto] , trovati ad Ashran, attiva i varchi."}
MultiLanguageSpellData['it'][178535] = {name = "Varco degli Stregoni", additional_info = "Portata illimitata\nIstantaneo\n[q]Gli Stregoni della Roccaforte di Scudo del Vento hanno attivato i Varchi degli Stregoni di Ashran, utili per spostarsi rapidamente nella zona.\n\n I Varchi degli Stregoni sono mostrati sulla mappa, nelle zone nord-ovest e sud-est di Ashran.\n\n Riportare a Marketa presso la Roccaforte di Scudo del Vento 400 [Frammenti di Manufatto] , trovati ad Ashran, attiva i varchi."}
MultiLanguageSpellData['it'][178536] = {name = "Cavalcalupi", additional_info = "Portata illimitata\nIstantaneo\n[q]I Cavalcalupi dell'Avamposto di Lancia da Guerra sono stati mandati a pattugliare la periferia di Ashran alla ricerca di membri dell'Alleanza.\n\n Per equipaggiare i Cavalcalupi servono i [Frammenti di Manufatto] che si trovano ad Ashran: bisogna portarli a Kalgan all'Avamposto di Lancia da Guerra."}
MultiLanguageSpellData['it'][178537] = {name = "Cavalieri", additional_info = "Portata illimitata\nIstantaneo\n[q]I Cavalieri della Roccaforte di Scudo del Vento sono stati mandati a pattugliare la periferia di Ashran alla ricerca di membri dell'Orda.\n\n Per equipaggiare i Cavalieri servono i [Frammenti di Manufatto] che si trovano ad Ashran: bisogna portarli a Valant Chiaraluce nella Roccaforte di Scudo del Vento."}
MultiLanguageSpellData['it'][178538] = {name = "Portale dei Maghi", additional_info = "Portata illimitata\nIstantaneo\n[q]I Maghi della Roccaforte di Scudo del Vento hanno attivato il Portale dei Maghi di Ashran, utile per tornare rapidamente alla Roccaforte.\n\n Il Portale dei Maghi è mostrato sulla mappa a ovest, vicino a Riposo dei Re.\n\n Riportare a Ecilam presso la Roccaforte di Scudo del Vento 400 [Frammenti di Manufatto] , trovati ad Ashran, attiva il portale."}
MultiLanguageSpellData['it'][178539] = {name = "Portale dei Maghi", additional_info = "Portata illimitata\nIstantaneo\n[q]I Maghi dell'Avamposto di Lancia da Guerra hanno attivato il Portale dei Maghi di Ashran, utile per tornare rapidamente all'Avamposto.\n\n Il Portale dei Maghi è mostrato sulla mappa a ovest, vicino a Riposo dei Re.\n\n Riportare a Fura presso l'Avamposto di Lancia da Guerra 400 [Frammenti di Manufatto] , trovati ad Ashran, attiva il portale."}
