MultiLanguageSpellData['it'][196468] = {name = "Guardacollo di Cuoio Pellesalda", additional_info = "1.5 s di lancio\nReagenti:\nCuoio Pellesalda Conciato (30)\nOggetto di missione\nUnico\n[q]\"Armatura per il collo della cavalcatura.\""}
MultiLanguageSpellData['it'][196469] = {name = "Groppiera di Cuoio Pellesalda", additional_info = "1.5 s di lancio\nReagenti:\nCuoio Pellesalda Conciato (50)\nOggetto di missione\nUnico\n[q]\"Armatura per il corpo della cavalcatura.\""}
MultiLanguageSpellData['it'][196470] = {name = "Vaso di Vetro Viola", additional_info = "2 s di lancio 5\n[q]La passione degli Alti Nobili per tutto ciò che è di colore viola precede la Guerra degli Antichi. I vasi di vetro erano piuttosto comuni e venivano utilizzati per contenere di tutto, dal grano ai lingotti d'oro."}
MultiLanguageSpellData['it'][196471] = {name = "Talismano di Fagliaroccia Inerte", additional_info = "2 s di lancio 5\n[q]Molti Alti Nobili per superstizione portavano pezzi di fagliaroccia come amuleti. Questi portafortuna erano generalmente indossati dai contadini, dagli studenti in difficoltà con gli esami o dal ceto medio, in bilico tra la nobiltà e la gente comune."}
MultiLanguageSpellData['it'][196472] = {name = "Fiala di Vinsilente", additional_info = "2 s di lancio 5\n[q]Vinsilente era un antico termine degli Alti Nobili usato per indicare un veleno. Ironicamente, dopo diecimila anni sottoterra, la sostanza ha perso la sua letalità e si è trasformata in una blanda bevanda alcolica."}
MultiLanguageSpellData['it'][196473] = {name = "Arazzo degli Alti Nobili Anteguerra", additional_info = "2 s di lancio 5\n[q]Gli arazzi prodotti prima del patto tra la Regina Azshara e i demoni avevano uno stile unico d'intreccio, con un motivo \"sotto-sopra-sopra\" che non è più stato usato in seguito."}
MultiLanguageSpellData['it'][196474] = {name = "Tagliacarte del Nobiluomo", additional_info = "2 s di lancio 5\n[q]Come spesso succede per i tagliacarte, questo oggetto è praticamente inutile per il suo scopo originale. Veniva però utilizzato spesso come arma da tenere sotto mano in situazioni in cui era socialmente inaccettabile portare con sé un pugnale."}
MultiLanguageSpellData['it'][196475] = {name = "Tamburo dell'Iniziazione", additional_info = "2 s di lancio 5\n[q]Non tutti i Tauren Alto Monte erano cacciatori, ma per coloro che lo erano, la prima uccisione veniva generalmente commemorata con un tamburo cerimoniale creato con la pelle della prima preda. La maggior parte dei Tamburi dell'Iniziazione era realizzata con pelli di coniglio o volpe. I cacciatori generalmente li portavano con sé per tutta la vita."}
MultiLanguageSpellData['it'][196476] = {name = "Amo di Osso d'Alce", additional_info = "2 s di lancio 5\n[q]L'osso d'alce era, ai tempi, il materiale più comune per la creazione di ami: era infatti sufficientemente solido per essere intagliato nella forma desiderata, ma estremamente flessibile per non rompersi nella bocca di un grosso salmone. Molti pescatori incidevano elaborati simboli nei loro \"ami fortunati\"."}
MultiLanguageSpellData['it'][196477] = {name = "Pietrapira Lisciata a Mano", additional_info = "2 s di lancio 5\n[q]La tradizione voleva che le vedove, i figli e i nipoti tenessero con sé una pietra proveniente dalla pira funeraria di un caro defunto. Queste pietre venivano tenute in tasca e toccate per ottenere coraggio o conforto, in memoria di una persona a cui si aveva voluto bene."}
MultiLanguageSpellData['it'][196478] = {name = "Buratto dei Drogbar", additional_info = "2 s di lancio 5\n[q]Benché molti Drogbar apprezzassero i bordi irregolari di una gemma grezza, altri preferivano un gioiello più liscio e regolare. Invece di sviluppare degli strumenti di taglio, facevano uso di una centrifuga in pietra in cui le gemme venivano fatte rotolare per numerose settimane. Questi strumenti, funzionanti a manovella, venivano generalmente operati da servi, schiavi o giovani disobbedienti."}
MultiLanguageSpellData['it'][196479] = {name = "Arco di Pietralegno", additional_info = "2 s di lancio 5\n[q]Le braccia dell'arco sono state ottenute da un legno duro come la roccia, che ha reso l'arma quasi impossibile da utilizzare. Gli archeologi non sono concordi se l'arco fosse originariamente così duro o se il legno si sia pietrificato con il passare degli anni. In ogni caso, la dimensione e il peso dell'arco suggeriscono che potesse essere usato solo dai più esperti cacciatori Tauren."}
MultiLanguageSpellData['it'][196480] = {name = "Coppa dell'Imp", additional_info = "2 s di lancio 5\n[q]Anche gli Imp devono bere, e molti preferiscono portare con sé una coppa personale. Alcuni ipotizzano l'esistenza di un'antica razza di Imp che considerava sacre le coppe con cui si abbeverava, e che parte di questo rituale sia rimasto anche dopo il loro arruolamento nella Legione Infuocata."}
MultiLanguageSpellData['it'][196481] = {name = "Cronache dalla Copertina Rovinata", additional_info = "2 s di lancio 5\n[q]Ogni razza di demone mantiene un comportamento differente tra una battaglia e l'altra. Le Succubi, per esempio, hanno l'abitudine di tenere dettagliati diari delle loro attività quotidiane. I loro resoconti sono spesso inquietanti, quasi grotteschi, e spesso sono scritti su della \"carta\" fatta con la pelle dei nemici."}
MultiLanguageSpellData['it'][196482] = {name = "Abissale Deforme", additional_info = "2 s di lancio 5\n[q]Il rituale per evocare un Abissale è complicato, e spesso non va a buon fine. Quando ciò accade, un piccolo pezzo del demone si può staccare, ribollendo in una combinazione di furia demoniaca e disperazione per la propria disfunzione. I campi di battaglia antichi sono pieni di pietre simili."}
MultiLanguageSpellData['it'][196483] = {name = "Globo del Caos Interiore", additional_info = "2 s di lancio 5\n[q]Il caos non viene naturale per tutti i demoni: alcuni fanno fatica ad adattarsi alle usanze della Legione Infuocata. Costoro spesso fanno uso di un globo incantato per invocare la rabbia richiesta da ogni demone che si rispetti. Non è noto come siano creati questi globi o chi li produca."}
MultiLanguageSpellData['it'][196484] = {name = "Usbergo di Dentemastino", additional_info = "2 s di lancio 5\n[q]Un massiccio pezzo di armatura per torso in \"maglia\", prodotto interamente utilizzando denti di segugi demoniaci. Le punte dei denti sono rivolte verso l'interno e verso l'alto, rendendo impossibile rimuovere l'armatura una volta indossata... perlomeno senza lacerare in profondità la carne di chi la indossa."}
