MultiLanguageSpellData['it'][207219] = {name = "Seguace: Signore delle Scimmie", additional_info = "Istantaneo\n[q]Il Signore delle Scimmie era il fidato compagno di Shaohao, imperatore di Pandaria. È curioso, astuto e conosce segreti indicibili sul passato di Pandaria."}
MultiLanguageSpellData['it'][207220] = {name = "Seguace: Angus Pugnoferreo", additional_info = "Istantaneo\n[q]Angus Pugnoferreo è nato col desiderio di combattere. Ama gli scontri faccia a faccia contro qualsiasi avversario ed è capace di sopraffare chiunque combinando le arti marziali, le prese, la lotta libera e un assortimento vario di pugni e calci."}
