MultiLanguageSpellData['it'][207222] = {name = "Seguace: Hiro", additional_info = "Istantaneo\n[q]Hiro ha viaggiato per il mondo per molti anni, passando da una locanda all'altra alla ricerca del bicchierino successivo. Non bisogna lasciarsi trarre in inganno dal suo aspetto trasandato: non solo ha un cuore d'oro, ma più beve, meglio combatte."}
MultiLanguageSpellData['it'][207223] = {name = "Seguace: Sylara Odeferrea", additional_info = "Istantaneo\n[q]Sylara Cuortetro è una misteriosa viaggiatrice che parla raramente del proprio passato. Una cosa è certa: niente la fa infuriare più di un'ingiustizia. Chiunque la incontri assaggerà le sue lame gemelle."}
MultiLanguageSpellData['it'][207224] = {name = "Quest Credit", additional_info = nil}
MultiLanguageSpellData['it'][207225] = {name = "Seguace: Aegira", additional_info = "Istantaneo\n[q]Aegira è un mastro birraio Vrykul, la prediletta di Odyn stesso. Le sue birre sono leggendarie. Pochi sanno, però, che anche le sue abilità in combattimento sono formidabili. Cresciuta sui campi di battaglia, non è mai stata sconfitta in un duello."}
