MultiLanguageSpellData['it'][207235] = {name = "Seguace: Celestos", additional_info = "Istantaneo\n[q]Il Consigliere Celestos è uno degli elementali più antichi e venerabili di Celaria.\n\n Durante il regno di Al'Akir, Celestos fu il capo consigliere e un tattico in molte delle campagne del Signore del Vento."}
MultiLanguageSpellData['it'][207236] = {name = "Seguace: Nobundo", additional_info = "Istantaneo\n[q]Il Chiaroveggente Nobundo, un tempo Paladino, fu il primo della sua gente a diventare uno Sciamano e a imparare a manipolare gli elementi.\n\n È uno degli Sciamani più saggi e potenti del Circolo della Terra, di cui è stato anche capo."}
MultiLanguageSpellData['it'][207237] = {name = "Seguace: Rehgar Terrafuriosa", additional_info = "Istantaneo\n[q]Rehgar Terrafuriosa è un potente Sciamano Elementale, un tempo gladiatore, esperto delle arti del combattimento.0$bCi sono pochi membri del Circolo della Terra che possono eguagliare l'esperienza e l'abilità di Rehgar sul campo di battaglia."}
MultiLanguageSpellData['it'][207238] = {name = "Seguace: Scaldius", additional_info = "Istantaneo\n[q]Un tempo luogotenente di Ragnaros, il Barone Scaldius ora serve il Signore del Fuoco Ardiron con impeccabile lealtà.0$bCon la potenza e la furia delle Terre del Fuoco al suo comando, il Barone Scaldius può facilmente incenerire tutti i nemici che osano affrontarlo."}
MultiLanguageSpellData['it'][207239] = {name = "Seguace: Valanghion", additional_info = "Istantaneo\n[q]Tra i grandi Signori di Pietra di Rocciafonda, Valanghion è conosciuto per essere praticamente indistruttibile.0$bValanghion ignora le normali emozioni mortali, come la paura o il dolore, ed esegue gli ordini del suo padrone con incrollabile determinazione."}
MultiLanguageSpellData['it'][207240] = {name = "Seguace: Muln Terra Furiosa", additional_info = "Istantaneo\n[q]Un tempo capo del Circolo della Terra, Muln Terra Furiosa è uno dei più grandi Sciamani della sua generazione.0$bLa sua presenza imponente sul campo di battaglia e la sua maestria nella vecchia scuola sciamanica lo rendono un alleato prezioso."}
