MultiLanguageSpellData['it'][213248] = {name = "Trasmutazione: Minerali in Stoffe", additional_info = "3 s di lancio 1 giorno di recupero\nReagenti:\nMinerale di Fagliaroccia (5), Vilardesia (5)\n[q]Trasmuta i minerali delle Isole Disperse in stoffe.\nProfessione:\nAlchimia di Legion\nScoperta:\nTrasmutazione Selvaggia\n\n\nMucchio di Seta\nSi vincola alla raccolta\n[q]\"Un cumulo di Seta Shal'dorei. Può contenere anche del Trasmutageno Viscoso.\"\n[q2]<Destra Aprire>"}
MultiLanguageSpellData['it'][213249] = {name = "Trasmutazione: Stoffe in Cuoio", additional_info = "3 s di lancio 1 giorno di recupero\nReagenti:\nSeta Shal'dorei (10)\n[q]Trasmuta le stoffe delle Isole Disperse in cuoio.\nProfessione:\nAlchimia di Legion\nScoperta:\nTrasmutazione Selvaggia\n\n\nMucchio di Pelli\nSi vincola alla raccolta\n[q]\"Un cumulo di Cuoio Pellesalda ed Elettroscaglie. Può contenere anche del Trasmutageno Viscoso.\"\n[q2]<Destra Aprire>"}
MultiLanguageSpellData['it'][213250] = {name = "Trasmutazione: Cuoio in Minerali", additional_info = "3 s di lancio 1 giorno di recupero\nReagenti:\nCuoio Pellesalda (5), Elettroscaglia (5)\n[q]Trasmuta il cuoio delle Isole Disperse in minerali.\nProfessione:\nAlchimia di Legion\nScoperta:\nTrasmutazione Selvaggia\n\nAmmasso di Minerali\nSi vincola alla raccolta\n[q]\"Un ammasso di Fagliaroccia e Vilardesia. Può contenere anche del Trasmutageno Viscoso.\"\n[q2]<Destra Aprire>"}
MultiLanguageSpellData['it'][213251] = {name = "Trasmutazione: Minerali in Erbe", additional_info = "3 s di lancio 1 giorno di recupero\nReagenti:\nMinerale di Fagliaroccia (5), Vilardesia (5)\n[q]Trasmuta i minerali delle Isole Disperse in erbe.\nProfessione:\nAlchimia di Legion\nScoperta:\nTrasmutazione Selvaggia\n\nMucchio di Erbe\nSi vincola alla raccolta\n[q]\"Un cumulo di erbe delle Isole Disperse. Può contenere anche del Trasmutageno Nero.\"\n[q2]<Destra Aprire>"}
