MultiLanguageSpellData['it'][214904] = {name = "Mordianime", additional_info = "Rango 1/ 20[q0]Tratto di Reperto\nRichiede Lame del Principe Caduto\n[q]Le tue lame hanno fame d'anime e squarciano l'essenza di quelle che colpiscono.\n\n Aumenta i danni inflitti del 1%."}
