MultiLanguageSpellData['it'][214906] = {name = "Ustione", additional_info = "Rango 1/ 20[q0]Tratto di Reperto\nRichiede Apocalisse\n[q]La lama oscura brucia la pelle al contatto, lasciando le vittime ad agonizzare.\n\n Aumenta i danni inflitti del 1%."}
MultiLanguageSpellData['it'][214907] = {name = "Combustione del Caos", additional_info = "Rango 1/ 20[q0]Tratto di Reperto\nRichiede Lame Gemelle dell'Ingannatore\n[q]Le energie caotiche instabili all'interno delle lame bruciano la carne dei nemici.\n\n Aumenta i danni inflitti del 1%."}
