MultiLanguageSpellData['it'][214909] = {name = "Divoranime", additional_info = "Rango 1/ 20[q0]Tratto di Reperto\nRichiede Lame da Guerra degli Aldrachi\n[q]Il potere delle innumerevoli anime risucchiate dalle lame ora rinsalda la tua resistenza.\n\n Aumenta l'armatura del 1%."}
MultiLanguageSpellData['it'][214910] = {name = "Furia di Goldrinn", additional_info = "Rango 1/ 20[q0]Tratto di Reperto\nRichiede Falce di Elune\n[q]Il tuo controllo del potere di Goldrinn cresce, permettendoti di lanciare incantesimi sempre più devastanti.\n\n Aumenta i danni inflitti del 1%."}
MultiLanguageSpellData['it'][214911] = {name = "Zanne Primeve", additional_info = "Rango 1/ 20[q0]Tratto di Reperto\nRichiede Zanne di Grigiomanto\n[q]Il tuo legame con l'avatar di Grigiomanto s'intensifica, permettendoti di sfruttare al meglio il suo potere.\n\n Aumenta i danni inflitti del 1%."}
MultiLanguageSpellData['it'][214912] = {name = "Vincolo di Ursoc", additional_info = "Rango 1/ 20[q0]Tratto di Reperto\nRichiede Artigli di Ursoc\n[q]Il tuo legame con il vigoroso avatar di Ursoc si fa più potente di giorno in giorno, rendendoti sempre più resiliente agli attacchi nemici.\n\n Aumenta l'armatura del 1%."}
MultiLanguageSpellData['it'][214913] = {name = "Bocciolo di G'hanir", additional_info = "Rango 1/ 20[q0]Tratto di Reperto\nRichiede G'hanir, l'Albero Madre\n[q]Man mano che la foresta cresce, anche G'hanir acquista potenza e i tuoi incantesimi fioriscono con maggiore efficacia.\n\n Aumenta le cure fornite del 1%."}
MultiLanguageSpellData['it'][214914] = {name = "Legaspirito", additional_info = "Rango 1/ 20[q0]Tratto di Reperto\nRichiede Titanassalto\n[q]Il vincolo di Hati con te si stringe sempre di più, aumentando la sua efficacia in battaglia.\n\n Aumenta i danni inflitti da te e dai tuoi famigli del 1.00%."}
MultiLanguageSpellData['it'][214915] = {name = "Frecce del Vento", additional_info = "Rango 1/ 20[q0]Tratto di Reperto\nRichiede Thas'dorah, Eredità dei Ventolesto\n[q]L'antica magica all'interno di questo arco fornisce il controllo dei venti, permettendo alle frecce di fendere l'aria con semplicità e di raggiungere sempre un risultato letale.\n\n Aumenta i danni inflitti del 1%."}
MultiLanguageSpellData['it'][214916] = {name = "Voce degli Dei Selvatici", additional_info = "Rango 1/ 20[q0]Tratto di Reperto\nRichiede Grinfiartiglio, Lancia degli Dei Selvatici\n[q]Dei Selvatici dai molti nomi guardano al portatore della lancia come al loro campione, e il loro potere fluisce sempre più forte dentro di te finché impugni Grinfiartiglio.\n\n Aumenta i danni inflitti del 1%."}
MultiLanguageSpellData['it'][214917] = {name = "Potere Antico", additional_info = "Rango 1/ 20[q0]Tratto di Reperto\nRichiede Aluneth, Granbastone di Aegwynn\n[q]L'entità caotica di Aluneth si piega alla tua volontà, potenziando ulteriormente i tuoi incantesimi.\n\n Aumenta i danni da arcano inflitti del 1%."}
MultiLanguageSpellData['it'][214918] = {name = "Lama Incantata Potenziata", additional_info = "Rango 1/ 20[q0]Tratto di Reperto\nRichiede Felo'melorn\n[q]Felo'melorn agisce come un condotto per gli incantesimi, potenziandone gli effetti devastanti.\n\n Aumenta i danni da fuoco inflitti del 1%."}
MultiLanguageSpellData['it'][214919] = {name = "Magia Innata", additional_info = "Rango 1/ 20[q0]Tratto di Reperto\nRichiede Gelonero, Granbastone di Alodi\n[q]Il potere scorre liberamente dentro Gelonero, permettendoti di gestire un potenziale sempre più spaventoso.\n\n Aumenta i danni da gelo inflitti del 1%."}
MultiLanguageSpellData['it'][214920] = {name = "Audacia del Nomade", additional_info = "Rango 1/ 20[q0]Tratto di Reperto\nRichiede Fu Zan, Compagno del Viandante\n[q]Il potere di Fu Zan trapela nel tuo essere, aumentando la tua resistenza in battaglia.\n\n Aumenta l'armatura del 1%."}
MultiLanguageSpellData['it'][214921] = {name = "Misticismo", additional_info = "Rango 1/ 20[q0]Tratto di Reperto\nRichiede Sheilun, Bastone delle Nebbie\n[q]Il potere di Sheilun sulle nebbie, inizialmente quasi soverchiante, sta diventando la tua seconda natura e perfeziona la tua maestria nel maneggiare queste energie.\n\n Aumenta le cure fornite del 1%."}
MultiLanguageSpellData['it'][214922] = {name = "Pugni del Vento Nascente", additional_info = "Rango 1/ 20[q0]Tratto di Reperto\nRichiede Pugni del Cielo\n[q]Il vento sussurra il tuo nome e soffia nei tuoi pugni, sempre più furioso man mano che combatti con queste armi.\n\n Aumenta i danni inflitti del 1%."}
MultiLanguageSpellData['it'][214923] = {name = "Tocco d'Argento", additional_info = "Rango 1/ 20[q0]Tratto di Reperto\nRichiede Mano d'Argento\n[q]La tua giusta causa e le tue azioni corrette si vincolano al martello del potente Tyr e così i tuoi incantesimi virtuosi diventano sempre più potenti.\n\n Aumenta le cure fornite del 1%."}
MultiLanguageSpellData['it'][214924] = {name = "Luce Implacabile", additional_info = "Rango 1/ 20[q0]Tratto di Reperto\nRichiede Scudo della Verità\n[q]Man mano che il suo potere cresce, lo Scudo della Verità protegge dai colpi con crescente facilità.\n\n Aumenta l'armatura del 2%."}
MultiLanguageSpellData['it'][214925] = {name = "Fiamma Proibita", additional_info = "Rango 1/ 20[q0]Tratto di Reperto\nRichiede Ira della Luce\n[q]Il potere instabile dell'Ira della Luce soccombe ai tuoi ordini, potenziando ulteriormente i tuoi incantesimi.\n\n Aumenta i danni inflitti, le cure e gli effetti di assorbimento forniti del 1%."}
MultiLanguageSpellData['it'][214926] = {name = "Faro di Luce", additional_info = "Rango 1/ 20[q0]Tratto di Reperto\nRichiede T'uure, Faro dei Naaru\n[q]Il tuo legame con T'uure è cresciuto nel corso del tempo, aumentando ulteriormente il potere già notevole che ti aveva donato.\n\n Aumenta le cure fornite del 1%."}
MultiLanguageSpellData['it'][214927] = {name = "Sussurri Oscuranti", additional_info = "Rango 1/ 20[q0]Tratto di Reperto\nRichiede Xal'atath, Lama dell'Impero Nero\n[q]Xal'atath sussurra oscure parole di potere nelle tue orecchie, regalandoti una conoscenza segreta per potenziare i tuoi incantesimi.\n\n Aumenta i danni da ombra inflitti del 1%."}
MultiLanguageSpellData['it'][214928] = {name = "Precisione del Sicario", additional_info = "Rango 1/ 20[q0]Tratto di Reperto\nRichiede Lame Sterminatrici di Re\n[q]Le innumerevoli uccisioni non fanno che aumentare la letalità di queste lame già temibili.\n\n Aumenta i danni inflitti del 1%."}
MultiLanguageSpellData['it'][214929] = {name = "Acciaio Maledetto", additional_info = "Rango 1/ 20[q0]Tratto di Reperto\nRichiede Lame dell'Oscurità\n[q]Le lame maledette ti riempiono del loro potere instabile, rendendo i tuoi attacchi ancora più letali.\n\n Aumenta i danni inflitti del 1%."}
MultiLanguageSpellData['it'][214930] = {name = "Lama della Legione", additional_info = "Rango 1/ 20[q0]Tratto di Reperto\nRichiede Zanne del Divoratore\n[q]Più queste armi colpiscono, più lo fanno con precisione e rapidità.\n\n Aumenta i danni inflitti del 1%."}
MultiLanguageSpellData['it'][214931] = {name = "Potere del Custode della Tempesta", additional_info = "Rango 1/ 20[q0]Tratto di Reperto\nRichiede Pugno di Ra-Den\n[q]Grazie al potere di Ra-Den i tuoi incantesimi si fanno sempre più devastanti.\n\n Aumenta i danni inflitti del 1%."}
MultiLanguageSpellData['it'][214932] = {name = "Colpi Frantumaterra", additional_info = "Rango 1/ 20[q0]Tratto di Reperto\nRichiede Martelfato\n[q]La tua maestria con Martelfato cresce, potenziando ulteriormente i tuoi attacchi.\n\n Aumenta i danni inflitti del 1%."}
MultiLanguageSpellData['it'][214933] = {name = "Flusso delle Maree", additional_info = "Rango 1/ 20[q0]Tratto di Reperto\nRichiede Sharas'dal, Scettro delle Maree\n[q]Un immenso potere scorre in Sharas'dal e la tua maestria nell'usarlo aumenta nel tempo.\n\n Aumenta le cure fornite del 1%."}
MultiLanguageSpellData['it'][214934] = {name = "Rubanima", additional_info = "Rango 1/ 20[q0]Tratto di Reperto\nRichiede Ulthalesh, Mietitrice di Ventomorto\n[q]Ulthalesh risponde alla tua chiamata, spaventando profondamente i nemici colpiti dalla tua magia.\n\n Aumenta i danni inflitti del 1%.[ Afflizione : Non modificata da Mietitura d'Anime ]"}
MultiLanguageSpellData['it'][214935] = {name = "Potere Persistente di Thal'kiel", additional_info = "Rango 1/ 20[q0]Tratto di Reperto\nRichiede Teschio dei Man'ari\n[q]Thal'kiel soccombe alla tua volontà, intensificando ulteriormente il tuo potere.\n\n Aumenta i danni inflitti del 1%."}
MultiLanguageSpellData['it'][214936] = {name = "Potere Rubato", additional_info = "Rango 1/ 20[q0]Tratto di Reperto\nRichiede Scettro di Sargeras\n[q]Continua a sbloccare il potere all'interno dello Scettro di Sargeras, che influenzerà anche i più remoti mondi della Legione.\n\n Aumenta i danni inflitti del 1%."}
MultiLanguageSpellData['it'][214937] = {name = "Acciaio Indistruttibile", additional_info = "Rango 1/ 20[q0]Tratto di Reperto\nRichiede Strom'kar, la Spezzaguerra\n[q]Man mano che la tua perizia con Strom'kar cresce, i suoi attacchi si fanno sempre più devastanti.\n\n Aumenta i danni inflitti del 1%."}
MultiLanguageSpellData['it'][214938] = {name = "Potere Titanico", additional_info = "Rango 1/ 20[q0]Tratto di Reperto\nRichiede Spadoni dei Valarjar\n[q]La furia indomita delle spade non fa che crescere ogni volta che le impugni.\n\n Aumenta i danni inflitti del 1%."}
MultiLanguageSpellData['it'][214939] = {name = "Baluardo Indistruttibile", additional_info = "Rango 1/ 20[q0]Tratto di Reperto\nRichiede Scaglia del Custode della Terra\n[q]Una scaglia di Neltharion è quasi indistruttibile, e il potere infuso nell'antico scudo ha potenziato questa resistenza.\n\n Aumenta l'armatura del 2%."}
