MultiLanguageSpellData['it'][215116] = {name = "Campione: Ombra di Akama", additional_info = "Istantaneo\n[q]Come ideatore del piano di Illidan di distruggere la Legione Infuocata, e come guida della Tribù Linguamorta, Akama si è dimostrato un capo pieno di risorse, uno stratega brillante e un abile combattente. La sua Ombra è tutto ciò e molto di più."}
MultiLanguageSpellData['it'][215117] = {name = "Campione: Matrona Suprema Malevola", additional_info = "Istantaneo\n[q]Malevola si è dimostrata più volte un'alleata preziosa. Di sicuro, se non fosse stato per lei, non saresti qui. Le sue capacità di comando sono pari solo alla sua padronanza della magia demoniaca."}
