MultiLanguageSpellData['it'][215127] = {name = "Rigurgito Fetido", additional_info = "Rigurgito Fetido Livello 80\n[q0][Item Effect]{Istantaneo} {20 s di recupero}\n[q]Consuma tutta la Poltiglia Coagulante per vomitare sui nemici frontali per 3 sec, infliggendo [ 390 * (1 + Versatility)] danni da natura per ogni poltiglia consumata."}
MultiLanguageSpellData['it'][215128] = {name = "Sangue Maledetto", additional_info = "Portata illimitata\nIstantaneo\n[q]Infetta il sangue dei personaggi con l'energia dell'Incubo, infliggendo 865 danni da ombra ogni 2 s per 8 sec. Al termine dell'effetto, il personaggio esplode, infliggendo 3959 danni da ombra agli alleati entro 11 m."}
MultiLanguageSpellData['it'][215129] = {name = "Campione: Altruis il Sofferente", additional_info = "Istantaneo\n[q]Altruis fu l'unico a opporsi all'idea di Illidan di combattere la Legione Infuocata a qualsiasi costo. È il Cacciatore di Demoni più forte mai conosciuto, e la sua abilità di combattimento è superata solo dalla sua acuta intelligenza e dal rispetto che si è guadagnato spingendo gli Illidari al cambiamento."}
MultiLanguageSpellData['it'][215131] = {name = "Zona di Celerità", additional_info = "{Istantaneo} {5 s di recupero}\n[q]Evoca un campo di energie arcane che aumenta la celerità di tutte le unità all'interno del campo del 50%."}
